values ('aaaa0003-0000-4000-8000-000000000006', 'it', 'it', 'Italian for Business', 'A CEFR B1 course in professional Italian: introduce yourself at work, run meetings, negotiate, write business emails, give presentations, and handle client calls with a confident formal register.', 'B1', 'work', 14, true, 'language', '{aaaa0003-0000-4000-8000-000000000003}')
