insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'aaaa0003-0000-4000-8000-000000000006', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Professional introductions', 'vocab', '{"items":[{"term":"Mi presento","translation":"Let me introduce myself","ipa":"mi preˈzɛn.to","example":"Buongiorno, mi presento: sono Elena Ricci, della Rossi & Partners."},{"term":"Mi occupo di","translation":"I am in charge of / I work in","ipa":"mi ˈɔk.ku.po di","example":"Mi occupo di marketing per il mercato europeo."},{"term":"Lavoro presso","translation":"I work at (a company)","ipa":"laˈvo.ro ˈprɛs.so","example":"Lavoro presso una società di consulenza a Torino."},{"term":"Le presento il mio collega","translation":"Let me introduce my colleague to you (formal)","ipa":"le preˈzɛn.to il ˈmi.o kolˈlɛ.ga","example":"Le presento il mio collega, il dottor Bianchi."},{"term":"Ecco il mio biglietto da visita","translation":"Here is my business card","ipa":"ˈɛk.ko il ˈmi.o biʎˈʎet.to da ˈvi.zi.ta","example":"Piacere. Ecco il mio biglietto da visita."},{"term":"Di cosa si occupa?","translation":"What do you do? (formal)","ipa":"di ˈkɔ.za si ˈɔk.ku.pa","example":"Molto lieto. E Lei, di cosa si occupa?"}]}'::jsonb, 'In business settings use the formal *Lei*, which takes third-person singular verbs: *Lei di cosa si occupa?* Introduce yourself with *Mi presento* before giving your role.', 8),
  (2, 'The formal register: dare del Lei', 'grammar', '{"sections":[{"heading":"Why Lei, and how it works","text":"In professional Italian you address a client or a new contact with *Lei*, not *tu*. Grammatically *Lei* behaves like the third-person singular *lei* (she), so the verb agrees the same way: *Come sta?* (How are you?), *Lei che ne pensa?* (What do you think?). Choosing *tu* too early can sound presumptuous; wait for the other person to propose *diamoci del tu* (let''s use tu)."},{"heading":"Pronouns and possessives","text":"Object pronouns follow suit: *La ringrazio* (I thank you), *Le mando il contratto* (I''ll send you the contract), where *La* is the direct object and *Le* the indirect. The polite possessive is *Suo/Sua*: *il Suo ufficio*, *la Sua proposta*. In writing, these forms are often capitalized as a mark of courtesy: *La ringrazio per la Sua email*."},{"heading":"Softening with titles","text":"Italians pair *Lei* with professional titles far more than English speakers do. Use *dottore/dottoressa* for any graduate, *ingegnere*, *avvocato*, *architetto* by profession, or simply *signore/signora* + surname. Drop the final *e* before a name: *dottor Bianchi*, *ingegner Conti*. A meeting that opens with *Buongiorno, dottoressa Ferri* sets exactly the right tone."},{"heading":"From formal to friendly","text":"The shift out of *Lei* is a small ritual. When rapport is established, the more senior or older person offers: *Possiamo darci del tu?* Accepting is easy: *Certo, volentieri!* From that point you switch to *tu* and second-person verbs. Until then, staying with *Lei* is the safe, respectful default in any first business contact."}]}'::jsonb, null, 12),
  (3, 'First meeting with a client', 'roleplay', '{"scenario":"You arrive at the Milan office of a potential client for a first meeting. Greet the client formally, introduce yourself and your company, exchange business cards, and set the agenda for the next thirty minutes.","persona":"A polite but time-conscious purchasing manager who expects the formal Lei and appreciates a clear agenda","goal":"Open the meeting professionally using Lei, introduce yourself and your role, and propose what you will discuss today"}'::jsonb, null, 10),
  (4, 'In the meeting room', 'vocab', '{"items":[{"term":"l''ordine del giorno","translation":"the agenda","ipa":"ˈlor.di.ne del ˈdʒor.no","example":"Il primo punto all''ordine del giorno è il budget."},{"term":"fare il punto della situazione","translation":"to take stock / review where we stand","ipa":"ˈfa.re il ˈpun.to ˈdel.la si.twaˈtsjo.ne","example":"Prima di decidere, facciamo il punto della situazione."},{"term":"Vorrei aggiungere una cosa","translation":"I''d like to add one thing","ipa":"vorˈrɛi adˈdʒun.dʒe.re ˈu.na ˈkɔ.za","example":"Scusi, vorrei aggiungere una cosa su questo punto."},{"term":"Sono d''accordo","translation":"I agree","ipa":"ˈso.no dakˈkɔr.do","example":"Sono d''accordo con la Sua analisi."},{"term":"prendere una decisione","translation":"to make a decision","ipa":"ˈprɛn.de.re ˈu.na de.tʃiˈzjo.ne","example":"Dobbiamo prendere una decisione entro venerdì."},{"term":"riassumere i punti principali","translation":"to sum up the main points","ipa":"ri.asˈsu.me.re i ˈpun.ti prin.tʃiˈpa.li","example":"In chiusura, riassumo i punti principali."}]}'::jsonb, 'Meetings run on soft conditional forms: *vorrei aggiungere* (I''d like to add), *potremmo* (we could). They sound collaborative rather than blunt.', 9),
  (5, 'The condizionale di cortesia', 'grammar', '{"sections":[{"heading":"Politeness through the conditional","text":"The conditional turns a demand into a request. Compare *voglio parlare col direttore* (I want to speak with the director) and *vorrei parlare col direttore* (I would like to speak with the director). In business, the second is almost always the right choice. The key verbs are *vorrei* (I''d like), *potrei/potrebbe* (I/you could), and *dovremmo* (we should)."},{"heading":"Forming the present conditional","text":"Take the future stem and add the conditional endings *-ei, -esti, -ebbe, -emmo, -este, -ebbero*. So *parlare* gives *parlerei, parleresti, parlerebbe...*. Common irregulars share their stem with the future: *avere → avrei*, *essere → sarei*, *potere → potrei*, *volere → vorrei*, *dovere → dovrei*. *Potrebbe ripetere?* means ''Could you repeat that?''"},{"heading":"Making requests land gently","text":"Use *potrebbe* + infinitive to ask someone to do something without pressure: *Potrebbe inviarmi il preventivo?* (Could you send me the quote?), *Potrebbe richiamarmi domani?* (Could you call me back tomorrow?). To offer or suggest, *potremmo* works well: *Potremmo fissare una riunione* (We could set up a meeting)."},{"heading":"Conditional for careful opinions","text":"The conditional also hedges an opinion so it feels less absolute: *Direi che il prezzo è alto* (I''d say the price is high), *Preferirei aspettare* (I''d rather wait). This softening is central to Italian business style, where disagreement is usually wrapped in *forse* (perhaps) and a conditional verb rather than stated flatly."}]}'::jsonb, null, 13),
  (6, 'Negotiating price and terms', 'roleplay', '{"scenario":"You are negotiating a supply contract. The supplier''s quote is higher than your budget. Ask for a discount, propose a longer commitment in exchange for a better price, and try to reach an agreement on payment terms.","persona":"An experienced Italian sales director who defends the price firmly but is open to a deal on volume and payment timing","goal":"Negotiate a better price and terms using polite conditional forms, and close with a clear next step"}'::jsonb, null, 12),
  (7, 'Writing business emails', 'vocab', '{"items":[{"term":"Gentile Dottoressa,","translation":"Dear Dr. (f.), (email opening)","ipa":"dʒenˈti.le dot.to.ˈres.sa","example":"Gentile Dottoressa Ferri, La ringrazio per il Suo messaggio."},{"term":"In riferimento alla Sua email","translation":"With reference to your email","ipa":"in ri.fe.riˈmen.to ˈal.la ˈsu.a ˈi.mejl","example":"In riferimento alla Sua email del 12 marzo, Le confermo la disponibilità."},{"term":"Le allego","translation":"I am attaching for you","ipa":"le alˈle.ɡo","example":"Le allego il preventivo aggiornato in formato PDF."},{"term":"Resto a disposizione","translation":"I remain at your disposal","ipa":"ˈrɛ.sto a dis.po.ziˈtsjo.ne","example":"Resto a disposizione per qualsiasi chiarimento."},{"term":"In attesa di un Suo riscontro","translation":"Awaiting your reply","ipa":"in atˈte.za di un ˈsu.o risˈkon.tro","example":"In attesa di un Suo riscontro, La saluto cordialmente."},{"term":"Cordiali saluti","translation":"Kind regards (email closing)","ipa":"korˈdja.li saˈlu.ti","example":"Cordiali saluti, Marco Greco."}]}'::jsonb, 'Italian business emails stay formal to the end: open with *Gentile* + title, close with *Cordiali saluti* or *Distinti saluti*, and keep the polite *La/Le* and capitalized *Suo* throughout.', 9),
  (8, 'Drafting a formal email', 'writing', '{"sections":[{"heading":"Structure of a business email","text":"A formal Italian email has four parts: the greeting (*Gentile...*), an opening line that states the reason for writing (*Le scrivo in merito a...* — I''m writing regarding...), the body, and a courteous close. Keep paragraphs short. Unlike English, the subject line often names the topic plainly: *Oggetto: Richiesta di preventivo*."},{"heading":"Openings and the polite subjunctive","text":"Requests are softened with the congiuntivo after verbs of wishing and after conjunctions like *affinché*: *Vorrei che mi inviaste il catalogo* (I''d like you to send me the catalogue), *Le scrivo affinché possiamo fissare un incontro* (I''m writing so that we can arrange a meeting). Practise *La pregherei di confermare* (I would ask you to confirm) — very common in formal correspondence."},{"heading":"The body: clear and courteous","text":"State one purpose per email. Announce attachments with *Le allego* or *In allegato trova...*. When you ask for something, use the conditional: *Le sarei grato se potesse...* (I would be grateful if you could...). This ''if you could'' clause pairs the conditional *sarei* with the imperfect subjunctive *potesse* — a fixed, high-register formula worth memorizing."},{"heading":"Closings and sign-off","text":"End by offering availability — *Resto a disposizione per ulteriori informazioni* — then a set-phrase closing. *Cordiali saluti* is the standard; *Distinti saluti* is more formal still; *Un cordiale saluto* is a touch warmer for a known contact. Sign with your full name and, on a first contact, your role and company beneath it."}]}'::jsonb, null, 12),
  (9, 'Handling a client call', 'roleplay', '{"scenario":"A client phones because a delivery is late. Answer professionally, apologize, explain the cause, and commit to a concrete solution and a follow-up. The connection is imperfect, so you may need to ask the caller to repeat.","persona":"A worried but reasonable client who wants a clear explanation and a firm new delivery date","goal":"Manage the call in formal Italian: apologize, explain, propose a solution, and confirm the next step by email"}'::jsonb, null, 11),
  (10, 'Checkpoint', 'quiz', '{"questions":[{"prompt":"Which form correctly addresses a new client formally?","options":["Come stai?","Come sta?","Come state?","Come vai?"],"answer":1,"explanation":"The formal Lei takes third-person singular verbs, so ''Come sta?'' is the polite ''How are you?''. ''Come stai?'' is informal tu."},{"prompt":"Complete politely: ''___ parlare con il direttore?''","options":["Voglio","Vorrei","Volevo","Vuoi"],"answer":1,"explanation":"The conditional ''vorrei'' (I would like) turns a blunt ''voglio'' (I want) into a courteous request — the condizionale di cortesia."},{"prompt":"In an email, what does ''Le allego il preventivo'' mean?","options":["I am calling you about the quote","I am attaching the quote for you","I am cancelling the quote","I already sent the quote"],"answer":1,"explanation":"''Le allego'' = ''I attach for you'', with the polite indirect pronoun Le. It announces an attachment, here the preventivo (quote)."},{"prompt":"Which is an appropriate formal email closing?","options":["Un bacio","Ciao ciao","Cordiali saluti","A presto"],"answer":2,"explanation":"''Cordiali saluti'' (Kind regards) is the standard formal sign-off. The others are informal and unsuitable for a business email."},{"prompt":"Choose the polite request to a supplier.","options":["Mandami il contratto!","Potrebbe inviarmi il contratto?","Devi mandare il contratto","Manda il contratto"],"answer":1,"explanation":"''Potrebbe inviarmi...?'' uses the conditional of potere with the formal Lei — a gentle, professional request. The others are imperatives to tu."},{"prompt":"Complete the high-register formula: ''Le sarei grato se ___ confermare.''","options":["può","potesse","puoi","potrà"],"answer":1,"explanation":"The fixed formula pairs the conditional ''sarei'' with the imperfect subjunctive ''potesse'': ''Le sarei grato se potesse confermare'' (I''d be grateful if you could confirm)."}]}'::jsonb, null, 8)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'aaaa0003-0000-4000-8000-000000000006' and l.position = v.pos
);
